-- Syntax errors read as Lua 5.1's: "<chunk>:<line>: <message> near
-- '<token>'", the line where the parser is, the token as luaX_lexerror
-- prints it (the text of a name, number or string as read, "<eof>",
-- "char(<n>)" for a control character). gopher-lua's yacc parser said
-- "syntax error" or "parse error" near the token for most of them, its lexer
-- "unterminated string", "Invalid token" and gave other lines.
local function try(src)
  local f, err = loadstring(src, "=src")
  if f then
    print("ok")
  else
    -- without the chunk name; control and non-ASCII bytes escaped
    err = err:gsub("^[^:]*:", ""):gsub("[^%w%p ]", function(c) return "\\" .. c:byte() end)
    print(err)
  end
end
